const churnPerSec = 12000; // client connects+disconnects per second
const cpuMsPerEvent = 0.05; // ms of single-core CPU per churn event
const cpuFraction = (churnPerSec * cpuMsPerEvent) / 1000; // fraction of one core
const verdict = cpuFraction > 0.7 ? 'AT RISK: single PgBouncer core near saturation from churn alone — run multiple instances + SO_REUSEPORT, or cut churn' : 'OK: one core has churn headroom';
console.log('cpuFraction=' + cpuFraction.toFixed(2) + ' ' + verdict);
